function ledgerDecodeLine(parts, length, decoder) {
  if (parts.length === 0) return "";
  if (parts.length === 1) return decoder.decode(parts[0]);

  const bytes = new Uint8Array(length);
  let offset = 0;

  for (const part of parts) {
    bytes.set(part, offset);
    offset += part.length;
  }

  return decoder.decode(bytes);
}

function ledgerIsBlank(line) {
  return /^[\x20\t\r]*$/.test(line);
}

async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");

  let accepted = 0;
  let rejected = 0;
  let lineNumber = 1;
  let reachedEOF = false;
  let cancelled = false;

  let parts = [];
  let bufferedLength = 0;

  async function cancelOnce() {
    if (!cancelled) {
      cancelled = true;
      await reader.cancel();
    }
  }

  async function visitText(text, line) {
    if (ledgerIsBlank(text)) return false;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return false;
    }

    accepted++;
    return (await visitor({ line, value })) === false;
  }

  try {
    while (true) {
      const { done, value: chunk } = await reader.read();

      if (done) {
        reachedEOF = true;

        if (bufferedLength > 0) {
          const text = ledgerDecodeLine(parts, bufferedLength, decoder);
          const stopped = await visitText(text, lineNumber);

          if (stopped) {
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      let start = 0;

      for (let i = 0; i < chunk.length; i++) {
        if (chunk[i] !== 0x0a) continue;

        if (i > start) {
          const part = chunk.subarray(start, i);
          parts.push(part);
          bufferedLength += part.length;
        }

        const text = ledgerDecodeLine(parts, bufferedLength, decoder);
        parts = [];
        bufferedLength = 0;

        const currentLine = lineNumber++;
        const stopped = await visitText(text, currentLine);

        if (stopped) {
          await cancelOnce();
          return { accepted, rejected, stopped: true };
        }

        start = i + 1;
      }

      if (start < chunk.length) {
        const part = chunk.subarray(start);
        parts.push(part);
        bufferedLength += part.length;
      }
    }
  } catch (error) {
    if (!reachedEOF) await cancelOnce();
    throw error;
  } finally {
    reader.releaseLock();
  }
}
